package com.moishow.identity;
import org.springframework.context.annotation.Profile;import org.springframework.stereotype.Service;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.context.ApplicationEventPublisher;import org.springframework.beans.factory.ObjectProvider;import org.springframework.transaction.annotation.*;
import java.time.*;import java.sql.Timestamp;import java.util.*;
import static com.moishow.identity.Models.*;import static com.moishow.identity.ApiProblem.require;
@Service @Profile("db")
class CommunityService implements PlatformContentAccess {
 final Store db;final JdbcTemplate sql;final ApplicationEventPublisher publisher;final ObjectProvider<AttachmentAccess> attachments;
 CommunityService(Store db,JdbcTemplate sql,ApplicationEventPublisher publisher,ObjectProvider<AttachmentAccess> attachments){this.db=db;this.sql=sql;this.publisher=publisher;this.attachments=attachments;}
 record MessageCreated(UUID roomId,Map<String,Object> message){}
 static Map<String,Object> view(Map<String,Object> row){var out=new LinkedHashMap<String,Object>();row.forEach((key,value)->{var p=key.split("_");var n=new StringBuilder(p[0]);for(int i=1;i<p.length;i++)n.append(Character.toUpperCase(p[i].charAt(0))).append(p[i].substring(1));out.put(n.toString(),value instanceof Timestamp t?t.toInstant():value);});return out;}
 static void pagination(int offset,int limit){require(offset>=0&&limit>=1&&limit<=200,400,"INVALID_PAGE");}
 static <T> List<T> page(List<T> values,int offset,int limit){pagination(offset,limit);return values.subList(Math.min(offset,values.size()),(int)Math.min((long)values.size(),(long)offset+limit));}
 List<Map<String,Object>> rows(String query,Object...args){return sql.queryForList(query,args).stream().map(CommunityService::view).toList();}
 boolean exists(String query,Object...args){return Boolean.TRUE.equals(sql.queryForObject(query,Boolean.class,args));}
 void social(Actor a){require(!exists("select exists(select 1 from platform_restriction where user_id=?)",a.userId()),403,"SOCIAL_RESTRICTED");}
 void socialNotice(Actor actor,UUID recipient,String group,String body){if(!actor.userId().equals(recipient)&&!blocked(actor.userId(),recipient))publisher.publishEvent(new DomainSignals.Notification(recipient,"SOCIAL",null,group,body));}
 boolean blocked(UUID a,UUID b){return exists("select exists(select 1 from community_block where (user_id=? and target_id=?) or (user_id=? and target_id=?))",a,b,b,a);}
 void pairLock(UUID a,UUID b){String pair=a.toString().compareTo(b.toString())<0?a+":"+b:b+":"+a;sql.queryForList("select pg_advisory_xact_lock(hashtextextended(?,0))",pair);}
 String nickname(UUID user,UUID club){var u=db.find(Account.class,user);var m=club==null?null:db.member(club,user);String name=m==null?u.nickname:m.nickname;return name+(u.status.equals("DELETED")?" · 탈퇴한 사용자":m!=null&&Set.of("LEFT","EXPELLED").contains(m.status)?" · 탈퇴한 멤버":"");}
 Map<String,Object> post(UUID id){var r=sql.queryForList("select * from community_post where id=? and status='ACTIVE'",id);require(!r.isEmpty(),404,"POST_NOT_FOUND");return r.getFirst();}
 void postAccess(Actor a,Map<String,Object> p){UUID club=(UUID)p.get("club_id");require(!blocked(a.userId(),(UUID)p.get("user_id")),403,"CONTENT_BLOCKED");if(club!=null)require(db.active(club,a.userId())&&db.find(Club.class,club).status.equals("ACTIVE"),403,"CLUB_MEMBER_REQUIRED");}
 @Override @Transactional(readOnly=true) public boolean canReadPost(Actor a,UUID id){try{postAccess(a,post(id));return true;}catch(ApiProblem e){return false;}}
 Map<String,Object> content(Actor a,Map<String,Object> row,UUID club){var result=view(row);result.put("nickname",nickname((UUID)row.get("user_id"),club));if(row.containsKey("kind")){UUID id=(UUID)row.get("id");result.put("photoIds",sql.queryForList("select file_id from community_post_photo where post_id=? order by position",UUID.class,id));result.put("likeCount",sql.queryForObject("select count(*) from community_like where post_id=?",Long.class,id));result.put("liked",exists("select exists(select 1 from community_like where post_id=? and user_id=?)",id,a.userId()));}return result;}
 @Transactional(readOnly=true) public Object posts(Actor a,int offset,int limit){pagination(offset,limit);var result=new ArrayList<Map<String,Object>>();sql.queryForList("select p.* from community_post p where p.status='ACTIVE' and ((p.club_id is null and (p.user_id=? or exists(select 1 from community_follow f where f.user_id=? and f.target_id=p.user_id))) or exists(select 1 from membership m join club c on c.id=m.club_id where m.club_id=p.club_id and m.user_id=? and m.status='ACTIVE' and not m.blacklisted and c.status='ACTIVE')) and not exists(select 1 from community_block b where (b.user_id=? and b.target_id=p.user_id) or (b.target_id=? and b.user_id=p.user_id)) order by p.created_at desc,p.id desc",a.userId(),a.userId(),a.userId(),a.userId(),a.userId()).forEach(p->result.add(content(a,p,(UUID)p.get("club_id"))));
  for(var e:db.list(ClubEvent.class,"from ClubEvent")){if(!db.find(Club.class,e.clubId).status.equals("ACTIVE")||blocked(a.userId(),e.hostId))continue;boolean member=db.active(e.clubId,a.userId());boolean followed=e.hostId.equals(a.userId())||exists("select exists(select 1 from community_follow where user_id=? and target_id=?)",a.userId(),e.hostId);if(!member&&!(e.publicEvent&&followed))continue;var card=new LinkedHashMap<String,Object>();card.put("id",e.id);card.put("eventId",e.id);card.put("clubId",e.clubId);card.put("userId",e.hostId);card.put("nickname",nickname(e.hostId,member?e.clubId:null));card.put("title",e.title);card.put("body",e.title);card.put("startsAt",e.startsAt);card.put("kind","RECRUITMENT");card.put("publicEvent",e.publicEvent);result.add(card);}return page(result,offset,limit);}
 @Transactional(readOnly=true) public Object getPost(Actor a,UUID id){var p=post(id);postAccess(a,p);return content(a,p,(UUID)p.get("club_id"));}
 void photos(Actor a,UUID id,UUID club,List<UUID> ids){if(ids==null)return;require(ids.stream().noneMatch(Objects::isNull)&&new HashSet<>(ids).size()==ids.size(),400,"INVALID_PHOTOS");var access=attachments.getIfAvailable();require(ids.isEmpty()||access!=null,503,"FILE_STORAGE_UNAVAILABLE");for(var file:ids)access.requirePostPhoto(a,file,club);sql.update("delete from community_post_photo where post_id=?",id);for(int i=0;i<ids.size();i++)sql.update("insert into community_post_photo(post_id,file_id,position) values(?,?,?)",id,ids.get(i),i);}
 public Object createPost(Actor a,CommunityController.PostForm b){social(a);String kind=b.kind()==null?"POST":b.kind();require(Set.of("POST","NOTICE").contains(kind),400,"INVALID_POST_KIND");if(b.clubId()!=null){var c=db.lock(Club.class,b.clubId());require(c.status.equals("ACTIVE")&&db.active(c.id,a.userId()),403,"CLUB_MEMBER_REQUIRED");}if(kind.equals("NOTICE"))require(b.clubId()!=null&&db.admin(b.clubId(),a.userId()),403,"CLUB_ADMIN_REQUIRED");UUID id=UUID.randomUUID();sql.update("insert into community_post(id,club_id,user_id,body,kind) values(?,?,?,?,?)",id,b.clubId(),a.userId(),ClubService.text(b.body(),10000),kind);photos(a,id,b.clubId(),b.photoIds());return content(a,post(id),b.clubId());}
 @Transactional(readOnly=true) public Object comments(Actor a,UUID id,int offset,int limit){pagination(offset,limit);var p=post(id);postAccess(a,p);return sql.queryForList("select c.* from community_comment c where c.post_id=? and c.status='ACTIVE' and not exists(select 1 from community_block b where (b.user_id=? and b.target_id=c.user_id) or (b.target_id=? and b.user_id=c.user_id)) order by c.created_at,c.id limit ? offset ?",id,a.userId(),a.userId(),limit,offset).stream().map(c->content(a,c,(UUID)p.get("club_id"))).toList();}
 public Object comment(Actor a,UUID id,CommunityController.BodyForm b){social(a);var p=lockPost(id);postAccess(a,p);UUID cid=UUID.randomUUID();sql.update("insert into community_comment(id,post_id,user_id,body) values(?,?,?,?)",cid,id,a.userId(),ClubService.text(b.body(),10000));socialNotice(a,(UUID)p.get("user_id"),"social:comments:"+id,"새 댓글이 등록됐어요.");return content(a,sql.queryForMap("select * from community_comment where id=?",cid),(UUID)p.get("club_id"));}
 Map<String,Object> lockPost(UUID id){var p=post(id);if(p.get("club_id")!=null)db.lock(Club.class,(UUID)p.get("club_id"));sql.queryForList("select id from community_post where id=? for update",id);return post(id);}
 void expected(Map<String,Object> row,Long version){require(version!=null&&version==((Number)row.get("version")).longValue(),409,"STALE_VERSION");}
 void archive(Actor a,Map<String,Object> row,String type,String action){sql.update("insert into community_content_revision(id,content_id,content_type,version,body,action,actor_id) values(?,?,?,?,?,?,?)",UUID.randomUUID(),row.get("id"),type,row.get("version"),row.get("body"),action,a.userId());}
 public Object editPost(Actor a,UUID id,CommunityController.EditForm b,boolean delete){social(a);var p=lockPost(id);postAccess(a,p);require(a.userId().equals(p.get("user_id")),403,"AUTHOR_REQUIRED");expected(p,b.version());if(p.get("kind").equals("NOTICE"))require(db.admin((UUID)p.get("club_id"),a.userId()),403,"CLUB_ADMIN_REQUIRED");archive(a,p,"POST",delete?"DELETE":"EDIT");if(delete){sql.update("update community_post set status='DELETED',version=version+1 where id=?",id);return Map.of("id",id,"status","DELETED","version",((Number)p.get("version")).longValue()+1);}photos(a,id,(UUID)p.get("club_id"),b.photoIds());sql.update("update community_post set body=?,version=version+1 where id=?",ClubService.text(b.body(),10000),id);return content(a,post(id),(UUID)p.get("club_id"));}
 public Object editComment(Actor a,UUID id,CommunityController.EditForm b,boolean delete){social(a);var list=sql.queryForList("select * from community_comment where id=? and status='ACTIVE'",id);require(!list.isEmpty(),404,"COMMENT_NOT_FOUND");UUID pid=(UUID)list.getFirst().get("post_id");var p=lockPost(pid);postAccess(a,p);var c=sql.queryForMap("select * from community_comment where id=? for update",id);require(c.get("status").equals("ACTIVE"),404,"COMMENT_NOT_FOUND");require(a.userId().equals(c.get("user_id")),403,"AUTHOR_REQUIRED");expected(c,b.version());archive(a,c,"COMMENT",delete?"DELETE":"EDIT");if(delete){sql.update("update community_comment set status='DELETED',version=version+1 where id=?",id);return Map.of("id",id,"status","DELETED","version",((Number)c.get("version")).longValue()+1);}sql.update("update community_comment set body=?,version=version+1 where id=?",ClubService.text(b.body(),10000),id);return content(a,sql.queryForMap("select * from community_comment where id=?",id),(UUID)p.get("club_id"));}
 public Object like(Actor a,UUID id,CommunityController.ToggleForm b){social(a);require(b.enabled()!=null,400,"ENABLED_REQUIRED");var p=lockPost(id);postAccess(a,p);if(b.enabled()){if(sql.update("insert into community_like(post_id,user_id) values(?,?) on conflict do nothing",id,a.userId())==1)socialNotice(a,(UUID)p.get("user_id"),"social:likes:"+id,"게시글에 새 좋아요가 있어요.");}else sql.update("delete from community_like where post_id=? and user_id=?",id,a.userId());return content(a,p,(UUID)p.get("club_id"));}
 public Object relation(Actor a,UUID target,String kind,CommunityController.ToggleForm b){if(!kind.equals("block"))social(a);require(b.enabled()!=null,400,"ENABLED_REQUIRED");require(!a.userId().equals(target),400,"INVALID_TARGET");db.find(Account.class,target);pairLock(a.userId(),target);require(Set.of("follow","block").contains(kind),404,"UNKNOWN_OPERATION");String table=kind.equals("follow")?"community_follow":"community_block";if(kind.equals("follow")&&b.enabled())require(!blocked(a.userId(),target)&&db.find(Account.class,target).status.equals("ACTIVE"),403,"USER_UNAVAILABLE");if(b.enabled()){int created=sql.update("insert into "+table+"(user_id,target_id) values(?,?) on conflict do nothing",a.userId(),target);if(kind.equals("follow")&&created==1)socialNotice(a,target,"social:followers","새 팔로워가 있어요.");}else sql.update("delete from "+table+" where user_id=? and target_id=?",a.userId(),target);return Map.of("userId",target,"enabled",b.enabled());}
 Map<String,Object> room(UUID id,boolean lock){var r=sql.queryForList("select * from community_room where id=?"+(lock?" for update":""),id);require(!r.isEmpty(),404,"ROOM_NOT_FOUND");return r.getFirst();}
 boolean roomAccess(Actor a,Map<String,Object> r,boolean messages){String kind=(String)r.get("kind");UUID id=(UUID)r.get("id");if(kind.equals("DIRECT")){UUID ua=(UUID)r.get("user_a"),ub=(UUID)r.get("user_b");return (a.userId().equals(ua)||a.userId().equals(ub))&&!blocked(ua,ub)&&(!messages||r.get("status").equals("ACTIVE")||r.get("status").equals("PENDING")&&exists("select exists(select 1 from community_message where room_id=?)",id));}if(kind.equals("GROUP_DM"))return exists("select exists(select 1 from community_room_member where room_id=? and user_id=? and status='ACTIVE')",id,a.userId());UUID club=(UUID)r.get("club_id");if(kind.equals("CLUB"))return db.find(Club.class,club).status.equals("ACTIVE")&&db.active(club,a.userId());var e=db.find(ClubEvent.class,(UUID)r.get("event_id"));return (e.hostId.equals(a.userId())||exists("select exists(select 1 from participation p join event_round r on r.id=p.round_id where r.event_id=? and p.user_id=? and p.ever_confirmed)",e.id,a.userId()));}
 boolean roomWrite(Actor a,Map<String,Object> r){if(!roomAccess(a,r,false))return false;String kind=(String)r.get("kind");if(kind.equals("DIRECT")){UUID other=a.userId().equals(r.get("user_a"))?(UUID)r.get("user_b"):(UUID)r.get("user_a");return db.find(Account.class,other).status.equals("ACTIVE")&&(r.get("status").equals("ACTIVE")||r.get("status").equals("PENDING")&&a.userId().equals(r.get("requester_id"))&&!exists("select exists(select 1 from community_message where room_id=?)",r.get("id")));}if(kind.equals("EVENT")){var e=db.find(ClubEvent.class,(UUID)r.get("event_id"));return (e.hostId.equals(a.userId())&&(e.responsibleId.equals(a.userId())||db.active(e.clubId,a.userId())))||exists("select exists(select 1 from participation p join event_round r on r.id=p.round_id where r.event_id=? and p.user_id=? and p.status='CONFIRMED')",e.id,a.userId());}return true;}
 @Override @Transactional(readOnly=true) public boolean canReadRoom(Actor a,UUID id){try{return roomAccess(a,room(id,false),true);}catch(ApiProblem ex){return false;}}
 @Override @Transactional(readOnly=true) public boolean canReadMessage(Actor a,UUID id){var messages=sql.queryForList("select * from community_message where id=? and status='ACTIVE'",id);if(messages.isEmpty())return false;var message=messages.getFirst();var r=room((UUID)message.get("room_id"),false);return roomAccess(a,r,true)&&visibleMessage(a,r,message);}
 boolean visibleMessage(Actor a,Map<String,Object> room,Map<String,Object> message){if(!room.get("kind").equals("GROUP_DM"))return true;var member=sql.queryForList("select min_sequence from community_room_member where room_id=? and user_id=? and status='ACTIVE'",room.get("id"),a.userId());return !member.isEmpty()&&((Number)message.get("sequence")).longValue()>=((Number)member.getFirst().get("min_sequence")).longValue()&&!blocked(a.userId(),(UUID)message.get("user_id"));}
 Map<String,Object> roomView(Actor a,Map<String,Object> r){var result=new LinkedHashMap<String,Object>();for(String key:List.of("id","kind","status","requester_id","club_id","event_id","created_at"))result.put(key,r.get(key));String kind=(String)r.get("kind");UUID club=(UUID)r.get("club_id");String title=kind.equals("DIRECT")?nickname(a.userId().equals(r.get("user_a"))?(UUID)r.get("user_b"):(UUID)r.get("user_a"),null):kind.equals("GROUP_DM")?(String)r.get("title"):kind.equals("CLUB")?db.find(Club.class,club).name:db.find(ClubEvent.class,(UUID)r.get("event_id")).title;result.put("title",title);var last=sql.queryForList("select * from community_message where room_id=? and status='ACTIVE' order by sequence desc",r.get("id")).stream().filter(m->visibleMessage(a,r,m)).findFirst();result.put("last_message",last.map(m->m.get("body")).orElse(""));result.put("last_message_at",last.map(m->m.get("created_at")).orElse(null));result.put("can_write",roomWrite(a,r));result.put("can_invite",kind.equals("GROUP_DM")&&roomAccess(a,r,true));return view(result);}
 @Transactional public Object rooms(Actor a,int offset,int limit){for(var c:db.list(Club.class,"select c from Club c, Membership m where c.id=m.clubId and m.userId=?1 and m.status='ACTIVE' and m.blacklisted=false and c.status='ACTIVE'",a.userId()))sql.update("insert into community_room(id,kind,club_id,status) values(?,'CLUB',?,'ACTIVE') on conflict do nothing",UUID.randomUUID(),c.id);for(var e:db.list(ClubEvent.class,"from ClubEvent")){var r=new HashMap<String,Object>();r.put("kind","EVENT");r.put("club_id",e.clubId);r.put("event_id",e.id);if(roomAccess(a,r,true))sql.update("insert into community_room(id,kind,club_id,event_id,status) values(?,'EVENT',?,?,'ACTIVE') on conflict do nothing",UUID.randomUUID(),e.clubId,e.id);}var visible=sql.queryForList("select * from community_room where status='ACTIVE'").stream().filter(r->roomAccess(a,r,false)).map(r->roomView(a,r)).sorted(Comparator.comparing((Map<String,Object> r)->(Instant)r.getOrDefault("lastMessageAt",null),Comparator.nullsLast(Comparator.reverseOrder())).thenComparing(r->r.get("id").toString())).toList();return page(visible,offset,limit);}
 boolean known(UUID a,UUID b){return exists("select exists(select 1 from community_follow where user_id=? and target_id=?) and exists(select 1 from community_follow where user_id=? and target_id=?)",a,b,b,a)||exists("select exists(select 1 from membership a join membership b on b.club_id=a.club_id join club c on c.id=a.club_id where a.user_id=? and b.user_id=? and a.status='ACTIVE' and b.status='ACTIVE' and not a.blacklisted and not b.blacklisted and c.status='ACTIVE')",a,b)||exists("select exists(select 1 from club_event e where (e.host_id=? or exists(select 1 from event_round r join participation p on p.round_id=r.id where r.event_id=e.id and p.user_id=? and p.status='CONFIRMED')) and (e.host_id=? or exists(select 1 from event_round r join participation p on p.round_id=r.id where r.event_id=e.id and p.user_id=? and p.status='CONFIRMED')))",a,a,b,b);}
 public Object direct(Actor a,CommunityController.DirectForm b){social(a);require(b.userId()!=null&&!a.userId().equals(b.userId()),400,"INVALID_TARGET");require(db.find(Account.class,b.userId()).status.equals("ACTIVE"),400,"INVALID_TARGET");pairLock(a.userId(),b.userId());require(!blocked(a.userId(),b.userId()),403,"USER_BLOCKED");UUID first=a.userId().toString().compareTo(b.userId().toString())<0?a.userId():b.userId(),second=first.equals(a.userId())?b.userId():a.userId();sql.update("insert into community_room(id,kind,user_a,user_b,requester_id,status) values(?,'DIRECT',?,?,?,?) on conflict do nothing",UUID.randomUUID(),first,second,a.userId(),known(a.userId(),b.userId())?"ACTIVE":"PENDING");var r=sql.queryForMap("select * from community_room where user_a=? and user_b=? and kind='DIRECT'",first,second);if(b.body()!=null&&!b.body().isBlank())send(a,(UUID)r.get("id"),new CommunityController.BodyForm(b.body()));return roomView(a,r);}
 @Transactional(readOnly=true) public Object requests(Actor a,int offset,int limit){return page(sql.queryForList("select * from community_room r where kind='DIRECT' and status='PENDING' and requester_id<>? and (user_a=? or user_b=?) and exists(select 1 from community_message m where m.room_id=r.id) order by created_at desc,id",a.userId(),a.userId(),a.userId()).stream().filter(r->roomAccess(a,r,true)).map(r->roomView(a,r)).toList(),offset,limit);}
 public Object accept(Actor a,UUID id,boolean decline){social(a);var original=room(id,false);require(original.get("kind").equals("DIRECT"),400,"DIRECT_ROOM_REQUIRED");pairLock((UUID)original.get("user_a"),(UUID)original.get("user_b"));var r=room(id,true);require(roomAccess(a,r,false)&&!a.userId().equals(r.get("requester_id")),403,"REQUEST_RECIPIENT_REQUIRED");require(r.get("status").equals("PENDING"),409,"REQUEST_ALREADY_DECIDED");sql.update("update community_room set status=? where id=?",decline?"DECLINED":"ACTIVE",id);return roomView(a,room(id,false));}
 @Transactional(readOnly=true) public Object messages(Actor a,UUID id,long after,int limit){pagination(0,limit);require(after>=0,400,"INVALID_CURSOR");var r=room(id,false);require(roomAccess(a,r,true),403,"ROOM_ACCESS_DENIED");return sql.queryForList("select * from community_message where room_id=? and sequence>? and status='ACTIVE' order by sequence",id,after).stream().filter(m->visibleMessage(a,r,m)).limit(limit).map(m->messageView(m,(UUID)r.get("club_id"))).toList();}
 Map<String,Object> messageView(Map<String,Object> raw,UUID club){var v=view(raw);v.put("nickname",nickname((UUID)raw.get("user_id"),club));return v;}
 public Object send(Actor a,UUID id,CommunityController.BodyForm b){social(a);var r=room(id,false);if(r.get("kind").equals("DIRECT"))pairLock((UUID)r.get("user_a"),(UUID)r.get("user_b"));else if(r.get("club_id")!=null){db.lock(Club.class,(UUID)r.get("club_id"));if(r.get("event_id")!=null)db.lock(ClubEvent.class,(UUID)r.get("event_id"));}r=room(id,true);require(roomWrite(a,r),403,"ROOM_ACCESS_DENIED");UUID mid=UUID.randomUUID();sql.update("insert into community_message(id,room_id,user_id,body) values(?,?,?,?)",mid,id,a.userId(),ClubService.text(b.body(),10000));var result=messageView(sql.queryForMap("select * from community_message where id=?",mid),(UUID)r.get("club_id"));publisher.publishEvent(new MessageCreated(id,result));if(r.get("kind").equals("DIRECT")&&r.get("status").equals("PENDING")){UUID recipient=a.userId().equals(r.get("user_a"))?(UUID)r.get("user_b"):(UUID)r.get("user_a");socialNotice(a,recipient,"chat:request:"+id,"새 대화 요청이 도착했어요.");}return result;}
 @Transactional(readOnly=true,propagation=Propagation.REQUIRES_NEW) public boolean deliveryAllowed(Actor a,UUID room){if(a==null||!a.scope().equals("ACTIVE"))return false;var s=db.session(a.sessionHash());if(s==null||s.revoked||!s.expiresAt.isAfter(Instant.now())||!db.find(Account.class,a.userId()).status.equals("ACTIVE"))return false;return canReadRoom(a,room);}
 @Transactional(readOnly=true,propagation=Propagation.REQUIRES_NEW) public boolean messageDeliveryAllowed(Actor a,UUID room,UUID message){if(!deliveryAllowed(a,room))return false;var rows=sql.queryForList("select * from community_message where id=? and room_id=? and status='ACTIVE'",message,room);return !rows.isEmpty()&&visibleMessage(a,room(room,false),rows.getFirst());}
}
